"use client"

import { Bell } from "lucide-react"
import {
  Button,
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
  ScrollArea,
} from "@aetherstack/ui"
import { cn } from "@aetherstack/utils"

export interface NotificationItem {
  id: string
  title: string
  description?: string
  timestamp?: string
  read?: boolean
}

export interface NotificationBellProps {
  count?: number
  notifications?: NotificationItem[]
  onMarkAllRead?: () => void
  onNotificationClick?: (id: string) => void
  className?: string
}

export function NotificationBell({
  count = 0,
  notifications = [],
  onMarkAllRead,
  onNotificationClick,
  className,
}: NotificationBellProps) {
  const displayCount = count > 99 ? "99+" : count > 0 ? String(count) : null
  const hasUnread = notifications.some((n) => !n.read)

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button
          variant="ghost"
          size="icon"
          aria-label={count > 0 ? `${count} unread notifications` : "Notifications"}
          className={cn("relative", className)}
        >
          <Bell className="h-5 w-5" aria-hidden="true" />
          {displayCount && (
            <span
              aria-hidden="true"
              className="bg-destructive text-destructive-foreground absolute -right-0.5 -top-0.5 flex h-4 min-w-4 items-center justify-center rounded-full px-1 text-[10px] font-semibold leading-none"
            >
              {displayCount}
            </span>
          )}
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-80">
        <div className="flex items-center justify-between px-2 py-1.5">
          <DropdownMenuLabel className="p-0 font-semibold">Notifications</DropdownMenuLabel>
          {onMarkAllRead && hasUnread && (
            <button
              type="button"
              onClick={onMarkAllRead}
              className="text-muted-foreground focus:ring-ring rounded text-xs underline-offset-2 hover:underline focus:outline-none focus:ring-1"
            >
              Mark all read
            </button>
          )}
        </div>
        <DropdownMenuSeparator />
        {notifications.length === 0 ? (
          <p className="text-muted-foreground py-8 text-center text-sm">No notifications</p>
        ) : (
          <ScrollArea className="max-h-72">
            {notifications.map((notification) => (
              <DropdownMenuItem
                key={notification.id}
                onClick={() => onNotificationClick?.(notification.id)}
                className={cn(
                  "focus:bg-accent flex cursor-pointer flex-col items-start gap-0.5 px-3 py-2.5",
                  !notification.read && "bg-accent/40",
                )}
              >
                <div className="flex w-full items-start justify-between gap-2">
                  <span className="text-sm font-medium leading-tight">{notification.title}</span>
                  {!notification.read && (
                    <span
                      aria-hidden="true"
                      className="bg-primary mt-1 h-2 w-2 shrink-0 rounded-full"
                    />
                  )}
                </div>
                {notification.description && (
                  <span className="text-muted-foreground line-clamp-1 text-xs">
                    {notification.description}
                  </span>
                )}
                {notification.timestamp && (
                  <span className="text-muted-foreground text-xs">{notification.timestamp}</span>
                )}
              </DropdownMenuItem>
            ))}
          </ScrollArea>
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}
